void SwigDirector_CustomLogger::Log(int level,std::string const &msg) {
  SWIG_PYTHON_THREAD_BEGIN_BLOCK;
  {
    swig::SwigVar_PyObject obj0;
    obj0 = SWIG_From_int(static_cast< int >(level));
    swig::SwigVar_PyObject obj1;
    obj1 = SWIG_From_std_string(static_cast< std::string >(msg));
    if (!swig_get_self()) {
      Swig::DirectorException::raise("'self' uninitialized, maybe you forgot to call CustomLogger.__init__.");
    }
#if defined(SWIG_PYTHON_DIRECTOR_VTABLE)
    const size_t swig_method_index = 0;
    const char *const swig_method_name = "Log";
    PyObject *method = swig_get_method(swig_method_index, swig_method_name);
    swig::SwigVar_PyObject result = PyObject_CallFunctionObjArgs(method ,(PyObject *)obj0,(PyObject *)obj1, NULL);
#else
    swig::SwigVar_PyObject swig_method_name = SWIG_Python_str_FromChar("Log");
    swig::SwigVar_PyObject result = PyObject_CallMethodObjArgs(swig_get_self(), (PyObject *) swig_method_name ,(PyObject *)obj0,(PyObject *)obj1, NULL);
#endif
    if (!result) {
      PyObject *error = PyErr_Occurred();
      {
        if (error != NULL) {
#if PY_MAJOR_VERSION >= 3
          PyObject *exc, *val, *tb;
          PyErr_Fetch(&exc, &val, &tb);
          PyErr_NormalizeException(&exc, &val, &tb);
          std::string err_msg("In method 'Log': ");
          
          PyObject* exc_str = PyObject_GetAttrString(exc, "__name__");
          PyObject* bytes = NULL;
          err_msg += SWIG_PyUnicode_AsUTF8AndSize(exc_str, NULL, &bytes);
          Py_XDECREF(exc_str);
          Py_XDECREF(bytes);
          
          if (val != NULL)
          {
            PyObject* val_str = PyObject_Str(val);
            bytes = NULL;
            err_msg += ": ";
            err_msg += SWIG_PyUnicode_AsUTF8AndSize(val_str, NULL, &bytes);
            Py_XDECREF(val_str);
            Py_XDECREF(bytes);
          }
          
          Py_XDECREF(exc);
          Py_XDECREF(val);
          Py_XDECREF(tb);
          
          Swig::DirectorMethodException::raise(err_msg.c_str());
#else
          throw Swig::DirectorMethodException();
#endif
        }
      }
    }
  }
  SWIG_PYTHON_THREAD_END_BLOCK;
}


